import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        boolean[] visited = new boolean[n + 1];
        int[] adj = new int[n];
        for (int i = 0; i < n; i++) {
            adj[i] = (i * k) % n;
        }

        int componentCount = 0;

        for (int start = 1; start < n; start++) {
            if (!visited[start]) {
                explore(start, adj, visited, n);
                componentCount++;
            }
        }

        long MOD = 1000000007L;

        if (k == 1) {
            System.out.println(pow(n, n, MOD));
        } else {
            System.out.println(pow(n, componentCount, MOD));
        }
    }

    private static void explore(int current, int[] adj, boolean[] visited, int n) {
        visited[current] = true;
        while (!visited[adj[current]]) {
            current = adj[current];
            visited[current] = true;
        }
    }

    private static long pow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
